package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.util.ElapsedTime;

// Generated by refract-suite ftc-construct. One button that does different things for a tap and for a hold. Call
// update() every loop with the button's level (gamepad1.options). One event per call at most:
//   PRESS  the loop the button goes down
//   TAP    released before HOLD_S (the caller reseeds the Pinpoint now, so a hold never does)
//   HOLD   still down after HOLD_S (once); the release after it gives no event
public final class OptionsGesture {
    public enum Event { NONE, PRESS, TAP, HOLD }

    public static final double HOLD_S = 1.5;

    private final ElapsedTime held = new ElapsedTime();
    private boolean down = false, consumed = false;

    public Event update(boolean pressed) {
        if (pressed && !down) {
            down = true;
            consumed = false;
            held.reset();
            return Event.PRESS;
        }
        if (pressed) {
            if (!consumed && held.seconds() >= HOLD_S) {
                consumed = true;
                return Event.HOLD;
            }
            return Event.NONE;
        }
        if (down) {
            down = false;
            return consumed ? Event.NONE : Event.TAP;
        }
        return Event.NONE;
    }

    // seconds the button has been down (0 when it is not)
    public double heldS() {
        return down ? held.seconds() : 0;
    }

    public boolean down() {
        return down;
    }
}
